import{_ as e,o as r,a,d as i}from"./chunks/framework.MWxrmMMs.js";const u=JSON.parse('{"title":"Серверы","description":"Серверы Minecraft в Stuzhik: создание и импорт, консоль с RCON, редактор server.properties, игроки, EULA, перезапуск при сбое и серверы друзей. Для Linux без окна есть консольная версия.","frontmatter":{"description":"Серверы Minecraft в Stuzhik: создание и импорт, консоль с RCON, редактор server.properties, игроки, EULA, перезапуск при сбое и серверы друзей. Для Linux без окна есть консольная версия.","head":[["meta",{"name":"keywords","content":"сервер minecraft, создать сервер minecraft, server.properties редактор, rcon minecraft, whitelist minecraft, сервер с модами, stuzhik сервер"}]]},"headers":[],"relativePath":"guide/servers.md","filePath":"guide/servers.md"}'),s={name:"guide/servers.md"};function d(n,t,o,l,h,p){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="серверы" tabindex="-1">Серверы <a class="header-anchor" href="#серверы" aria-label="Permalink to &quot;Серверы&quot;">​</a></h1><p>Сервер устроен так же, как сборка, только без графики: со своими модами, миром и настройками. Создаётся, ставится и запускается из лаунчера. Для сервера на Linux без окна есть <a href="/guide/cli.html">консольная версия</a>: данные у неё общие с приложением.</p><h2 id="создание" tabindex="-1">Создание <a class="header-anchor" href="#создание" aria-label="Permalink to &quot;Создание&quot;">​</a></h2><ul><li><strong>«Создать» → сервер</strong>: версия игры и загрузчик, как у клиента</li><li><strong>Импорт сервера</strong>: Ctrl+K → «Импорт» → вкладка «Сервер», там «Папка сервера» с уже готовым сервером. Лаунчер сам определит версию игры, загрузчик, порт и число игроков</li><li><strong>«Конвертация в сервер»</strong> в меню клиентской сборки: клиентские моды (карты, шейдеры, интерфейс) отключатся сами</li></ul><p>Перед первым запуском лаунчер спрашивает согласие с EULA Minecraft: без него сервер не запускается.</p><h2 id="вкладки-сервера" tabindex="-1">Вкладки сервера <a class="header-anchor" href="#вкладки-сервера" aria-label="Permalink to &quot;Вкладки сервера&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Вкладка</th><th>Что там</th></tr></thead><tbody><tr><td>Консоль</td><td>вывод сервера и команды</td></tr><tr><td>Моды, Датапаки</td><td>моды и датапаки сервера</td></tr><tr><td>Модпак</td><td>обновление модпака, если сервер поставлен из него</td></tr><tr><td>Файлы, Профили</td><td>редактор конфигов</td></tr><tr><td>Настройки сервера</td><td>server.properties, игроки, EULA</td></tr><tr><td>Бэкапы</td><td>резервные копии сервера и его мира</td></tr><tr><td>Анализ логов</td><td>разбор краша сервера (<a href="/guide/log-analyzer.html">Анализатор логов</a>)</td></tr></tbody></table><p>Во вкладке «Моды» кнопка «Клиентские моды» находит моды, которые серверу не нужны, и отключает их.</p><h2 id="консоль" tabindex="-1">Консоль <a class="header-anchor" href="#консоль" aria-label="Permalink to &quot;Консоль&quot;">​</a></h2><p>Вывод сервера в реальном времени, фильтр «Все» / «Ошибки» и история команд стрелками ↑↓. «Остановить сервер (stop)» сохраняет мир; «Принудительно завершить» обрывает процесс и может потерять данные.</p><p>Если на сервере включён RCON, команды идут через него, консоль показывает, сколько игроков онлайн, и работает «Сказать»: сообщение всем игрокам. RCON выключен по умолчанию: включите его и задайте пароль в «Настройки сервера» → «Настройки» → «RCON». Пароль лежит в server.properties, поэтому не открывайте порт RCON в интернет.</p><h2 id="настроики-сервера" tabindex="-1">Настройки сервера <a class="header-anchor" href="#настроики-сервера" aria-label="Permalink to &quot;Настройки сервера&quot;">​</a></h2><ul><li><strong>Настройки</strong>: server.properties по группам: сеть, мир, геймплей, производительность, безопасность, RCON, Query. Значения сохраняются так, как написаны (длинный сид мира не превратится в другое число). Изменения вступают в силу после перезапуска</li><li><strong>Игроки</strong>: whitelist, операторы и баны. На сервере без проверки лицензии работает и с офлайн-никами</li><li><strong>EULA</strong>: принять соглашение Minecraft</li></ul><p>В «Редактировать» у сервера есть порт и «Перезапускать при сбое»: упавший сервер поднимется сам.</p><h2 id="friends-servers" tabindex="-1">Серверы друзей <a class="header-anchor" href="#friends-servers" aria-label="Permalink to &quot;Серверы друзей {#friends-servers}&quot;">​</a></h2><p>В «Друзьях» видны серверы, которые друзья открыли, и те, на которых они сейчас играют. У сервера видно, как он сейчас: задержку, сколько игроков онлайн, версию и сообщение сервера, как в списке серверов в самой игре. Лаунчер спрашивает сервер, когда вы открываете его комнату, и по кнопке «Спросить ещё раз»; не ответил, так и пишет.</p><p>«Зайти» скачивает сборку сервера (или докачивает то, чего не хватает), подставляет адрес и запускает игру. Подробнее о друзьях и передаче сборок: <a href="/guide/connect.html">Stuzhik Connect</a>.</p>',17)])])}const f=e(s,[["render",d]]);export{u as __pageData,f as default};
